export const ARQUIVOS = Object.keys(DESFAZ)
export function semRostoNoClipe2810(text, rel) {
  if (typeof text !== 'string') return text
  const original = text
  const hunks = DESFAZ[String(rel ?? '').replace(/\\/g, '/').replace(/^\.\//, '')]
  if (!hunks || !original.includes(MARCA)) return original
  const crlf = original.includes('\r\n')
  let s = '\n' + original.replace(/\r\n/g, '\n') + '\n'
  for (const h of hunks) {
    const parts = s.split('\n' + h.now + '\n')
    if (parts.length !== 2) throw new Error('semRostoNoClipe2810: ' + rel + ' mudou fora da camada (' + (parts.length - 1) + 'x)')
    s = parts.join('\n' + h.before + '\n')
  }
  s = s.slice(1, -1)
  if (s.includes(MARCA)) throw new Error('semRostoNoClipe2810: sobrou linha marcada em ' + rel)
  return crlf ? s.replace(/\n/g, '\r\n') : s
}
